func replay(t *testing.T) http.RoundTripper {
	t.Helper()

	interactions, err := cassette.InteractionsReadFile("../../api/interactions.json")
	if err != nil {
		t.Fatal(err)
	}

	rec := cassette.Replay(interactions, cassette.InOrder(), cassette.WithMatcher(cassette.MatchRequest(
		cassette.CompareHeaders("User-Agent"),
	)))

	t.Cleanup(func() {
		if unused := rec.Unused(); len(unused) > 0 {
			t.Errorf("%d recorded interactions were never replayed, the first: %s %s", len(unused), unused[0].Request.Method, &unused[0].Request.URL)
		}
	})

	return rec
}

func TestClient_Interactions(t *testing.T) {
	ctx := t.Context()
	t.Setenv("TOGGL_API_USERNAME", "user")
	t.Setenv("TOGGL_API_PASSWORD", "pass")

	c, err := NewClient(WithHTTPClient(&http.Client{Transport: replay(t)}))
	if err != nil {
		t.Fatal(err)
	}

	if _, err := c.GetMe(ctx, &GetMeParams{}); err != nil {
		t.Fatalf("GetMe: %v", err)
	}

	if _, err := c.GetMe(ctx, &GetMeParams{
		WithRelatedData: true,
	}); err != nil {
		t.Fatalf("GetMe: %v", err)
	}

	if _, err := c.GetMe(ctx, &GetMeParams{
		WithRelatedData: true,
	}); err == nil {
		t.Fatal("GetMe: expected error")
	} else if _, ok := errors.AsType[*api.ErrorBody](err); !ok {
		t.Fatalf("GetMe: got: %T, want: *api.ErrorBody", err)
	}

	if _, err := c.ListTimeEntries(ctx, &ListTimeEntriesParams{
		StartDate: time.Date(2026, 10, 9, 15, 32, 44, 0, time.FixedZone("", 7200)),
		EndDate:   time.Date(2026, 10, 23, 15, 32, 44, 0, time.FixedZone("", 7200)),
	}); err != nil {
		t.Fatalf("ListTimeEntries: %v", err)
	}

	if _, err := c.StopTimeEntry(ctx, 2230580, 4598868048); err == nil {
		t.Fatal("StopTimeEntry: expected error")
	} else if _, ok := errors.AsType[*APIErrorString](err); !ok {
		t.Fatalf("StopTimeEntry: got: %T, want: *APIErrorString", err)
	}
}
